function read(){let x=JSON.parse(fs.readFileSync(DB,'utf8'));x.investments??=[];x.accounts??=[];x.budgets??=[];x.projects??=[];x.timeEntries??=[];x.habits??=[];x.habitLogs??=[];x.subscriptions??=[];x.debts??=[];x.footballTeams??=[];x.matches??=[];x.news??=[];x.movies??=[];x.timers??=[];x.exercise??=[];x.weeklyNotes??=[];x.mediaLog??=[];x.investmentTx??=[];x.assetPrices??=[];x.priceAlerts??=[];x.portfolioSnapshots??=[];x.newsSources??=[];x.contacts??=[];x.contactLogs??=[];x.learning??=[];x.bookmarks??=[];x.shoppingItems??=[];x.trips??=[];x.tripChecklist??=[];x.documents??=[];x.goals??=[];x.wins??=[];x.decisions??=[];x.lifeReviews??=[];return x}function write(x){fs.writeFileSync(DB,JSON.stringify(x,null,2))}
function json(res,status,data){res.writeHead(status,{'Content-Type':'application/json; charset=utf-8'});res.end(JSON.stringify(data))}
function body(req){return new Promise((ok,no)=>{let d='';req.on('data',x=>d+=x);req.on('end',()=>{try{ok(d?JSON.parse(d):{})}catch(e){no(e)}})})}
function hash(p,s){return crypto.pbkdf2Sync(p,s,130000,32,'sha256').toString('hex')}
function id(){return crypto.randomUUID()}function cookie(req){return Object.fromEntries((req.headers.cookie||'').split(';').filter(Boolean).map(x=>x.trim().split('=')))}
function me(req,db){let sid=cookie(req).sid;let s=db.sessions.find(x=>x.id===sid);return s&&db.users.find(x=>x.id===s.userId)}
class AuthError extends Error{}
function auth(req,res,db){let u=me(req,db);if(!u){json(res,401,{error:'ابتدا وارد حساب شوید.'});throw new AuthError()}return u}
function today(){return new Date().toISOString().slice(0,10)}
function filterTransactions(db,userId,u){let from=u.searchParams.get('from'),to=u.searchParams.get('to'),month=u.searchParams.get('month'),account=u.searchParams.get('account'),category=u.searchParams.get('category'),minAmount=u.searchParams.get('minAmount'),maxAmount=u.searchParams.get('maxAmount');if(!from&&!to){month=month||today().slice(0,7);from=month+'-01';to=month+'-31'}return db.transactions.filter(x=>x.userId===userId&&x.date>=from&&x.date<=(to||from)&&(!account||x.account===account)&&(!category||x.category===category)&&(!minAmount||x.amount>=Number(minAmount))&&(!maxAmount||x.amount<=Number(maxAmount))).sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt-a.createdAt)}
function csvEscape(v){v=String(v??'');return /[",\n]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v}
function advanceRecurringTransactions(db,userId){let chains={};db.transactions.forEach(x=>{if(x.userId===userId&&x.recurrenceId)(chains[x.recurrenceId]=chains[x.recurrenceId]||[]).push(x)});let changed=false;for(const list of Object.values(chains)){let latest=list.sort((a,b)=>b.date.localeCompare(a.date))[0];if(!latest.recurrence)continue;let next=new Date(latest.date+'T12:00:00');if(latest.recurrence==='weekly')next.setDate(next.getDate()+7);else if(latest.recurrence==='monthly')next.setMonth(next.getMonth()+1);else next.setDate(next.getDate()+1);let nextDate=next.toISOString().slice(0,10);if(nextDate<=today()&&!list.some(x=>x.date===nextDate)){db.transactions.push({id:id(),userId,title:latest.title,amount:latest.amount,category:latest.category,kind:latest.kind,account:latest.account,date:nextDate,recurrence:latest.recurrence,recurrenceId:latest.recurrenceId,receipt:null,createdAt:Date.now()});changed=true}}return changed}
function enNum(v){return String(v).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d))}
function parseLifeText(text){let t=enNum(text),actions=[],m=t.match(/(?:خرید(?:م)?|خرج کردم|هزینه)[^\d]{0,25}(\d[\d,]*)/);if(m){let a=Number(m[1].replace(/,/g,''));actions.push({type:'transaction',amount:a,title:'هزینه ثبت‌شده از متن',category:/نان|رستوران|شام|غذا|کافه/.test(t)?'خوراک':'متفرقه'})}let w=t.match(/(\d+(?:\.\d+)?)\s*(?:ساعت|ساعتِ?)\s*(?:روی|کار)/);if(w)actions.push({type:'time',minutes:Math.round(Number(w[1])*60),title:'کار ثبت‌شده از متن'});let mood=t.match(/(?:حالم|مود)[^\d]{0,12}(\d{1,2})/);if(mood)actions.push({type:'mood',value:Math.min(10,Number(mood[1]))});let sleep=t.match(/(\d+(?:\.\d+)?)\s*ساعت\s*(?:خواب|خوابیدم)/);if(sleep)actions.push({type:'sleep',value:sleep[1]+' ساعت'});return actions}
async function aiComplete(system,userMsg,maxTokens){if(!AI_PROVIDER_API_KEY)return null;let r=await fetch('https://api.anthropic.com/v1/messages',{method:'POST',headers:{'x-api-key':AI_PROVIDER_API_KEY,'anthropic-version':'2023-06-01','content-type':'application/json'},body:JSON.stringify({model:AI_MODEL,max_tokens:maxTokens||800,system,messages:[{role:'user',content:userMsg}]})}).then(r=>r.json());if(r.error)throw new Error(r.error.message||'خطای مدل هوش مصنوعی');return(r.content&&r.content[0]&&r.content[0].text)||''}
async function aiExtractActions(text){if(!AI_PROVIDER_API_KEY)return[];let sys='اعمال زیر را از متن فارسی کاربر استخراج کن و فقط یک آرایهٔ JSON برگردان، بدون هیچ توضیح اضافه. هر آیتم یکی از این ساختارهاست: {"type":"transaction","amount":عدد,"title":"...","category":"..."} یا {"type":"time","minutes":عدد,"title":"..."} یا {"type":"mood","value":عدد بین ۰ تا ۱۰} یا {"type":"sleep","value":"عدد ساعت"}. اگر چیزی برای استخراج نبود، آرایهٔ خالی [] برگردان.';try{let out=await aiComplete(sys,text,400);let m=out&&out.match(/\[[\s\S]*\]/);if(!m)return[];let arr=JSON.parse(m[0]);return Array.isArray(arr)?arr.filter(a=>a&&typeof a==='object'&&['transaction','time','mood','sleep'].includes(a.type)):[]}catch(e){return[]}}
function pearson(xs,ys){let n=xs.length;if(n<3)return null;let mx=xs.reduce((a,b)=>a+b,0)/n,my=ys.reduce((a,b)=>a+b,0)/n,num=0,dx2=0,dy2=0;for(let i=0;i<n;i++){let dx=xs[i]-mx,dy=ys[i]-my;num+=dx*dy;dx2+=dx*dx;dy2+=dy*dy}let den=Math.sqrt(dx2*dy2);return den===0?null:num/den}
function correlationLabel(r){if(r===null)return{strength:'داده کافی نیست',direction:null};let a=Math.abs(r),direction=r>=0?'مثبت':'منفی',strength=a<0.2?'ناچیز':a<0.5?'ضعیف':a<0.7?'متوسط':'قوی';return{strength,direction}}
function parseSleepHours(v){if(!v)return null;let m=String(v).match(/(\d+(?:\.\d+)?)/);return m?Number(m[1]):null}
const CATEGORY_KEYWORDS=[['خوراک',/نان|رستوران|شام|ناهار|صبحانه|غذا|کافه|سوپرمارکت|میوه|قصاب|نانوایی|فست\s?فود/],['حمل‌ونقل',/تاکسی|اسنپ|تپسی|بنزین|پمپ\s?بنزین|مترو|اتوبوس|پارکینگ|تعمیر\s?ماشین|بلیط|مسافرت/],['قبض',/قبض|برق|آب و فاضلاب|گاز|اینترنت|تلفن|شارژ\s?خط|بیمه/],['سلامت',/دکتر|پزشک|دارو|داروخانه|بیمارستان|درمانگاه|دندانپزشک|آزمایشگاه/],['تفریح',/سینما|کنسرت|بازی|فیلم|پارک|تفریح|بولینگ|بیلیارد/],['پوشاک',/لباس|کفش|پوشاک|مانتو|شلوار|کاپشن/],['آموزش',/کتاب|دوره|کلاس|آموزش|شهریه|دانشگاه/],['مسکن',/اجاره|رهن|شارژ\s?ساختمان|مسکن/]];
function suggestCategoryKeyword(title){let t=String(title||'');for(const[cat,re]of CATEGORY_KEYWORDS)if(re.test(t))return cat;return null}
function decodeXmlEntities(s){return String(s||'').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g,'$1').replace(/<[^>]+>/g,' ').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#0?39;/g,"'").replace(/&apos;/g,"'").replace(/\s+/g,' ').trim()}
function extractTag(block,tag){let m=block.match(new RegExp('<'+tag+'[^>]*>([\\s\\S]*?)<\\/'+tag+'>','i'));return m?m[1]:''}
function extractAttr(block,tag,attr){let m=block.match(new RegExp('<'+tag+'[^>]*\\b'+attr+'=["\']([^"\']*)["\']','i'));return m?m[1]:''}
function parseFeed(xml){let itemBlocks=xml.match(/<item\b[\s\S]*?<\/item>/gi),isAtom=false;if(!itemBlocks){itemBlocks=xml.match(/<entry\b[\s\S]*?<\/entry>/gi)||[];isAtom=true}let items=[];for(const block of itemBlocks){let title=decodeXmlEntities(extractTag(block,'title'));let link=isAtom?(extractAttr(block,'link','href')||decodeXmlEntities(extractTag(block,'link'))):decodeXmlEntities(extractTag(block,'link'));let summaryRaw=extractTag(block,'description')||extractTag(block,'summary')||extractTag(block,'content:encoded')||extractTag(block,'content');let summary=decodeXmlEntities(summaryRaw).slice(0,600);let pubDate=decodeXmlEntities(extractTag(block,'pubDate')||extractTag(block,'published')||extractTag(block,'updated'));let guid=decodeXmlEntities(extractTag(block,'guid')||extractTag(block,'id'))||link;if(title)items.push({title,link,summary,pubDate,guid:guid||link||title})}return items}
function isMostlyLatin(text){let t=String(text||'').replace(/[^A-Za-z؀-ۿ]/g,'');if(!t)return false;let latin=(t.match(/[A-Za-z]/g)||[]).length;return latin/t.length>0.6}
function periodRange(period,periodKey){if(period==='yearly')return{from:periodKey+'-01-01',to:periodKey+'-12-31'};if(period==='monthly'){let days=new Date(Number(periodKey.slice(0,4)),Number(periodKey.slice(5,7)),0).getDate();return{from:periodKey+'-01',to:periodKey+'-'+String(days).padStart(2,'0')}}let end=new Date(periodKey+'T12:00:00');end.setDate(end.getDate()+6);return{from:periodKey,to:end.toISOString().slice(0,10)}}
function computeGoalProgress(db,userId,goal){let{from,to}=periodRange(goal.period,goal.periodKey);if(goal.linkedType==='habit'){return db.habitLogs.filter(l=>l.habitId===goal.linkedId&&l.done&&l.date>=from&&l.date<=to).length}if(goal.linkedType==='finance'){return db.transactions.filter(x=>x.userId===userId&&x.category===goal.linkedId&&x.date>=from&&x.date<=to&&x.kind==='expense').reduce((n,x)=>n+x.amount,0)}if(goal.linkedType==='learning'){let item=db.learning.find(x=>x.id===goal.linkedId&&x.userId===userId);return item&&item.progressTotal?Math.round(item.progressCurrent/item.progressTotal*100):0}return goal.manualValue||0}
function nextAnnualOccurrence(dateStr){let m=String(dateStr||'').match(/(\d{2})-(\d{2})$/);if(!m)return null;let mo=Number(m[1]),da=Number(m[2]),y=new Date().getFullYear(),cand=new Date(Date.UTC(y,mo-1,da)),t=new Date();t.setUTCHours(0,0,0,0);if(cand<t)cand=new Date(Date.UTC(y+1,mo-1,da));return cand.toISOString().slice(0,10)}
function textSimilarityScore(a,b){let wa=new Set(String(a||'').toLowerCase().split(/[^\p{L}\p{N}]+/u).filter(w=>w.length>2)),wb=new Set(String(b||'').toLowerCase().split(/[^\p{L}\p{N}]+/u).filter(w=>w.length>2));let common=0;for(const w of wa)if(wb.has(w))common++;return common}
async function syncOneNewsSource(db,userId,src){let added=0;try{let r=await fetch(src.url,{headers:{'User-Agent':'Mozilla/5.0 (compatible; HasteRSS/1.0)'}});if(!r.ok)throw new Error('HTTP '+r.status);let xml=await r.text(),parsed=parseFeed(xml);let existingGuids=new Set(db.news.filter(x=>x.userId===userId&&x.source===src.name).map(x=>x.guid).filter(Boolean));for(const it of parsed.slice(0,30)){if(!it.guid||existingGuids.has(it.guid))continue;db.news.push({id:id(),userId,title:it.title,source:src.name,category:src.category,url:it.link||'',summary:it.summary||'',date:today(),saved:false,guid:it.guid,createdAt:Date.now()});existingGuids.add(it.guid);added++}src.lastSyncAt=Date.now();src.lastError=null;return{source:src.name,ok:true,found:parsed.length,added}}catch(e){src.lastError=e.message;return{source:src.name,ok:false,error:e.message,added:0}}}
async function syncAllNewsSources(db){let results=[],changed=false;for(const user of db.users){for(const src of db.newsSources.filter(x=>x.userId===user.id&&x.active)){let r=await syncOneNewsSource(db,user.id,src);if(r.added)changed=true;results.push(r)}}return{changed,results}}
async function rapidApiGet(host,path){if(!RAPIDAPI_KEY)return null;let r=await fetch('https://'+host+path,{headers:{'x-rapidapi-key':RAPIDAPI_KEY,'x-rapidapi-host':host}}),data=await r.json();if(!r.ok)throw new Error((data&&(data.message||data.error))||'خطا در دریافت داده از RapidAPI');return data}
