let tgOffset=0;
function tgApi(method,params){if(!TELEGRAM_BOT_TOKEN)return Promise.resolve(null);return fetch(`https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/${method}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(params||{})}).then(r=>r.json())}
function tgSend(chatId,text){return tgApi('sendMessage',{chat_id:chatId,text})}
async function handleTelegramMessage(msg){let db=read(),fromId=String(msg.from.id),chatId=msg.chat.id,text=(msg.text||'').trim();let user=db.users.find(u=>u.telegramUserId===fromId);if(!user)return tgSend(chatId,'این حساب تلگرام به هیچ حسابِ هِسته وصل نیست. از تنظیمات اپ، شناسهٔ عددی تلگرامت رو وصل کن.');let d=today();
 if(text.startsWith('/')){let cmd=text.split(' ')[0];
  if(cmd==='/امروز'){let tasks=db.tasks.filter(x=>x.userId===user.id&&x.date===d),done=tasks.filter(x=>x.done).length,expense=db.transactions.filter(x=>x.userId===user.id&&x.date===d&&x.kind==='expense').reduce((n,x)=>n+x.amount,0),daily=db.daily.find(x=>x.userId===user.id&&x.date===d);return tgSend(chatId,`امروز:\nتسک‌ها: ${done} از ${tasks.length}\nهزینه: ${expense.toLocaleString('fa-IR')} تومان\nحال: ${daily?daily.mood+'/10':'ثبت نشده'}`)}
  if(cmd==='/موجودی'){let accounts=db.accounts.filter(x=>x.userId===user.id&&!x.archived),balances={};db.transactions.filter(x=>x.userId===user.id).forEach(x=>{let a=x.account||'بدون حساب';if(x.kind==='transfer'){balances[a]=(balances[a]||0)-x.amount;let b=x.toAccount||'بدون حساب';balances[b]=(balances[b]||0)+x.amount}else balances[a]=(balances[a]||0)+(x.kind==='income'?x.amount:-x.amount)});let lines=accounts.map(a=>`${a.name}: ${((a.openingBalance||0)+(balances[a.name]||0)).toLocaleString('fa-IR')} تومان`);return tgSend(chatId,lines.length?lines.join('\n'):'حسابی ثبت نشده.')}
  if(cmd==='/پرتفوی'){let totals=portfolioTotals(computeHoldings(db,user.id)),lines=Object.entries(totals).map(([cur,t])=>`${cur}: ارزش ${t.value.toLocaleString('fa-IR')} · سود/زیان ${(t.unrealizedPnl+t.realizedPnl+t.dividends-t.fees).toLocaleString('fa-IR')}`);return tgSend(chatId,lines.length?lines.join('\n'):'هنوز دارایی‌ای ثبت نشده.')}
  if(cmd==='/گزارش_ماه'){let month=d.slice(0,7),t=db.transactions.filter(x=>x.userId===user.id&&x.date.startsWith(month)),expense=t.filter(x=>x.kind==='expense').reduce((n,x)=>n+x.amount,0),income=t.filter(x=>x.kind==='income').reduce((n,x)=>n+x.amount,0);return tgSend(chatId,`گزارش ${month}:\nدرآمد: ${income.toLocaleString('fa-IR')}\nهزینه: ${expense.toLocaleString('fa-IR')}\nمانده: ${(income-expense).toLocaleString('fa-IR')}`)}
  return tgSend(chatId,'فرمان‌های موجود: /امروز /موجودی /پرتفوی /گزارش_ماه')}
 let actions=parseLifeText(text);if(!actions.length&&AI_PROVIDER_API_KEY){try{actions=await aiExtractActions(text)}catch(e){}}let done=[],daily=db.daily.find(x=>x.userId===user.id&&x.date===d);for(const a of actions){if(a.type==='transaction'&&Number(a.amount)>0){let amount=Number(a.amount);db.transactions.push({id:id(),userId:user.id,title:String(a.title||'هزینه ثبت‌شده از متن'),amount,category:String(a.category||'متفرقه'),kind:'expense',account:'بدون حساب',date:d,createdAt:Date.now()});done.push('هزینه '+amount.toLocaleString('fa-IR')+' تومان')}if(a.type==='time'&&Number(a.minutes)>0){let minutes=Math.round(Number(a.minutes));db.timeEntries.push({id:id(),userId:user.id,title:String(a.title||'کار ثبت‌شده از متن'),projectId:null,minutes,date:d,createdAt:Date.now()});done.push('کار '+minutes+' دقیقه')}if(a.type==='mood'||a.type==='sleep'){if(!daily){daily={id:id(),userId:user.id,date:d,mood:7,energy:7,sleep:'',note:''};db.daily.push(daily)}if(a.type==='mood'&&Number(a.value)>=0&&Number(a.value)<=10){daily.mood=Number(a.value);done.push('مود '+Number(a.value))}else if(a.type==='sleep'&&a.value){daily.sleep=String(a.value);done.push('خواب '+String(a.value))}}}write(db);return tgSend(chatId,done.length?'ثبت شد: '+done.join(' · '):'چیزی قابل تشخیص نبود. مثلاً بنویس: «۵۰ هزار تومان ناهار خوردم» یا «۲ ساعت کار کردم».')}
async function tgPollLoop(){if(!TELEGRAM_BOT_TOKEN)return;while(true){try{let res=await tgApi('getUpdates',{offset:tgOffset,timeout:25});if(res&&res.ok)for(const u of res.result){tgOffset=u.update_id+1;if(u.message&&u.message.text!==undefined){let p=dbLock.then(()=>handleTelegramMessage(u.message),()=>handleTelegramMessage(u.message));dbLock=p.catch(()=>{});await p.catch(e=>console.error('tg handle error',e))}}}catch(e){console.error('tg poll error',e);await new Promise(r=>setTimeout(r,3000))}}}
async function tgCheckReports(){if(!TELEGRAM_BOT_TOKEN)return;let db=read(),now=new Date(),hh=now.getHours(),d=today(),changed=false;for(const user of db.users){if(!user.telegramUserId)continue;if(hh===8&&user.tgLastMorning!==d){user.tgLastMorning=d;changed=true;let soon=new Date();soon.setDate(soon.getDate()+3);let soonStr=soon.toISOString().slice(0,10);let subs=db.subscriptions.filter(x=>x.userId===user.id&&!x.archived&&x.nextDate<=soonStr).length,debts=db.debts.filter(x=>x.userId===user.id&&!x.settled&&x.dueDate&&x.dueDate<=soonStr).length,matchesToday=db.matches.filter(x=>x.userId===user.id&&x.date===d&&x.status==='upcoming');let lines=[`صبح بخیر ${user.name}! امروز ${d} است.`];if(subs)lines.push(`${subs} اشتراک سررسید نزدیک دارد.`);if(debts)lines.push(`${debts} بدهی/طلب سررسید نزدیک دارد.`);matchesToday.forEach(m=>lines.push(`امروز${m.time?' ساعت '+m.time:''} بازی ${m.home} - ${m.away} داری.`));await tgSend(user.telegramUserId,lines.join('\n'))}if(hh===21&&user.tgLastEvening!==d){user.tgLastEvening=d;changed=true;let tasks=db.tasks.filter(x=>x.userId===user.id&&x.date===d),doneCount=tasks.filter(x=>x.done).length,daily=db.daily.find(x=>x.userId===user.id&&x.date===d);let lines=[`گزارش شب: ${doneCount} از ${tasks.length} تسک امروز انجام شد.`];if(!daily)lines.push('هنوز روزنگار امروز رو ثبت نکردی.');await tgSend(user.telegramUserId,lines.join('\n'))}}if(changed)write(db)}
if(TELEGRAM_BOT_TOKEN){tgPollLoop();setInterval(()=>{let p=dbLock.then(tgCheckReports,tgCheckReports);dbLock=p.catch(()=>{})},5*60*1000)}
async function refreshPricesAndAlerts(){let db=read(),changed=await refreshAllCryptoPrices(db).catch(()=>false),now=Date.now();for(const user of db.users){let holdings=computeHoldings(db,user.id);for(const t of evaluateAlerts(db,user.id,holdings)){let a=t.alert;if(!a.lastNotifiedAt||now-a.lastNotifiedAt>6*3600*1000){a.lastNotifiedAt=now;changed=true;if(TELEGRAM_BOT_TOKEN&&user.telegramUserId)await tgSend(user.telegramUserId,'🔔 '+t.text)}}}if(changed)write(db)}
setInterval(()=>{let p=dbLock.then(refreshPricesAndAlerts,refreshPricesAndAlerts);dbLock=p.catch(()=>{})},15*60*1000);
async function backgroundNewsSync(){let db=read(),{changed}=await syncAllNewsSources(db).catch(()=>({changed:false}));if(changed)write(db)}
setInterval(()=>{let p=dbLock.then(backgroundNewsSync,backgroundNewsSync);dbLock=p.catch(()=>{})},30*60*1000);
